{"path":"app/api/handlers.py","file_text":""""Request handlers."""

from app.services import users

MAX_TERMS = 5
MAX_TERM_LENGTH = 30


def handle_get_user(params: dict) -> tuple[int, dict]:
    raw = params.get("id")
    if not isinstance(raw, str) or not raw.isdigit():
        return 400, {"error": "invalid id"}
    user = users.get_user(int(raw))
    if user is None:
        return 404, {"error": "not found"}
    return 200, user


def handle_search_terms(params: dict) -> tuple[int, dict]:
    raw_terms = params.get("terms")
    if not isinstance(raw_terms, list) or not 1 <= len(raw_terms) <= MAX_TERMS:
        return 400, {"error": "invalid terms"}
    terms = []
    for term in raw_terms:
        if not isinstance(term, str):
            return 400, {"error": "invalid terms"}
        trimmed = term.strip()
        if not trimmed or len(trimmed) > MAX_TERM_LENGTH:
            return 400, {"error": "invalid terms"}
        terms.append(trimmed)
    return 200, {"users": users.search_users(terms)}
"}

